    INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, "order")
    VALUES 
    (v_topic_id, 'Alveolar ventilation is best described by:', '["Respiratory rate × tidal volume", "(Tidal volume − dead space) × respiratory rate", "Residual volume × respiratory rate", "Functional residual capacity × respiratory rate", "Total lung capacity − tidal volume"]', 1, 'Alveolar ventilation measures the volume of fresh air that actually reaches the gas exchange surface per minute.', 1),
    (v_topic_id, 'A decrease in alveolar ventilation will most directly cause:', '["Decreased PaCO2", "Increased PaCO2", "Increased alveolar PO2", "Decreased arterial PCO2", "Respiratory alkalosis"]', 1, 'Reduced ventilation prevents CO2 from being expelled, leading to CO2 accumulation (hypercapnia).', 2),
    (v_topic_id, 'Hypoventilation typically causes:', '["Respiratory alkalosis", "Respiratory acidosis", "Metabolic alkalosis", "Metabolic acidosis", "No change in blood pH"]', 1, 'Hypercapnia from hypoventilation leads to an increase in H+ ions, causing respiratory acidosis.', 3),
    (v_topic_id, 'Hyperventilation typically causes:', '["Increased PaCO2 and decreased pH", "Decreased PaCO2 and increased pH", "Increased bicarbonate immediately", "Decreased PaO2", "Metabolic alkalosis as primary event"]', 1, 'Blowing off too much CO2 causes respiratory alkalosis.', 4),
    (v_topic_id, 'The primary function of surfactant is to:', '["Increase surface tension", "Decrease surface tension", "Increase airway resistance", "Decrease lung compliance", "Increase pleural pressure"]', 1, 'Surfactant reduces the work of breathing and stabilizes alveoli by lowering surface tension.', 5),
    (v_topic_id, 'Surfactant is produced mainly by:', '["Type I pneumocytes", "Type II pneumocytes", "Alveolar macrophages", "Pulmonary capillary endothelial cells", "Ciliated epithelial cells"]', 1, 'Type II pneumocytes are specialized cells that secrete pulmonary surfactant.', 6),
    (v_topic_id, 'According to Laplace law, alveolar pressure is proportional to:', '["Radius ÷ surface tension", "Surface tension ÷ radius", "Compliance × volume", "Flow × resistance", "Volume ÷ pressure"]', 1, 'P = 2T / r. Pressure is directly proportional to surface tension and inversely proportional to radius.', 7),
    (v_topic_id, 'Without surfactant, small alveoli would tend to:', '["Expand more than large alveoli", "Collapse into larger alveoli", "Have lower pressure than large alveoli", "Become completely rigid", "Have no effect on gas exchange"]', 1, 'According to Laplace Law, smaller alveoli would have higher pressure and collapse into larger ones without surfactant.', 8),
    (v_topic_id, 'Surfactant increases lung compliance by:', '["Increasing elastic recoil", "Reducing surface tension", "Increasing airway smooth muscle tone", "Increasing alveolar dead space", "Increasing pleural fluid volume"]', 1, 'Decreased surface tension makes it easier to inflate the lungs.', 9),
    (v_topic_id, 'In a normal person at rest, intrapleural pressure is usually:', '["Positive relative to atmosphere", "Equal to alveolar pressure", "Negative relative to atmosphere", "Zero at all times", "Greater than pulmonary capillary pressure"]', 2, 'The opposing elastic forces of the lung and chest wall create a sub-atmospheric vacuum.', 10),
    (v_topic_id, 'Transpulmonary pressure is:', '["Intrapleural pressure − alveolar pressure", "Alveolar pressure − intrapleural pressure", "Atmospheric pressure − alveolar pressure", "Capillary pressure − pleural pressure", "Venous pressure − alveolar pressure"]', 1, 'Ptp = Palv - Ppl. It represents the pressure gradient that keeps the lung inflated.', 11),
    (v_topic_id, 'During quiet inspiration, alveolar pressure becomes:', '["Slightly positive relative to atmosphere", "Slightly negative relative to atmosphere", "Equal to intrapleural pressure", "Constantly zero", "Greater than venous pressure"]', 1, 'Expansion of the thoracic cavity lowers alveolar pressure below atmospheric, drawing air in.', 12),
    (v_topic_id, 'During quiet inspiration, the diaphragm:', '["Relaxes and ascends", "Contracts and descends", "Does not move", "Increases intrathoracic pressure", "Decreases thoracic volume"]', 1, 'Contraction of the diaphragm increases thoracic volume, leading to inspiration.', 13),
    (v_topic_id, 'In pneumothorax, the lung collapses mainly because:', '["Surfactant production stops", "Intrapleural pressure approaches atmospheric pressure", "Alveolar PO2 becomes zero", "Pulmonary perfusion ceases", "The diaphragm becomes paralyzed"]', 1, 'Loss of the pleural vacuum allows the lung''s natural elastic recoil to collapse it.', 14),
    (v_topic_id, 'Tidal volume is the volume of air:', '["Remaining after maximal expiration", "Inspired or expired during a normal breath", "Expired after a maximal inspiration", "Remaining after normal expiration", "That cannot be measured by spirometry"]', 1, 'TV is the air moved during a standard breath cycle.', 15),
    (v_topic_id, 'Functional residual capacity is the volume remaining in the lungs after:', '["Maximal inspiration", "Normal expiration", "Maximal expiration", "Forced expiration in one second", "Normal inspiration"]', 1, 'FRC = RV + ERV. It is the volume in the lungs at the end of a normal exhale.', 16),
    (v_topic_id, 'Residual volume is the volume remaining after:', '["Normal expiration", "Maximal expiration", "Normal inspiration", "Tidal inspiration", "Forced inspiration"]', 1, 'RV is the amount of air that cannot be exhaled even with maximal effort.', 17),
    (v_topic_id, 'Which of the following cannot be measured directly by simple spirometry?', '["Tidal volume", "Inspiratory reserve volume", "Vital capacity", "Residual volume", "Forced vital capacity"]', 3, 'RV, FRC, and TLC require advanced techniques like helium dilution or body plethysmography.', 18),
    (v_topic_id, 'Total lung capacity equals:', '["Vital capacity + residual volume", "Tidal volume + inspiratory reserve volume", "Functional residual capacity − expiratory reserve volume", "Vital capacity − residual volume", "Inspiratory capacity + tidal volume"]', 0, 'TLC is the total volume of air the lungs can hold.', 19),
    (v_topic_id, 'In obstructive lung disease, the FEV1/FVC ratio is typically:', '["Increased", "Decreased", "Normal only", "Always 100%", "Unchanged despite severe disease"]', 1, 'Reduced ratio is the hallmark of diseases like asthma and COPD.', 20),
    (v_topic_id, 'In restrictive lung disease, the FEV1/FVC ratio is usually:', '["Decreased markedly", "Normal or increased", "Zero", "Lower than obstructive disease", "Equal to residual volume"]', 1, 'Restrictive disease lowers both values proportionally, keeping the ratio stable or even high.', 21),
    (v_topic_id, 'Residual volume is commonly increased in obstructive lung disease because of:', '["Increased elastic recoil", "Air trapping", "Decreased airway resistance", "Increased surfactant", "Reduced lung compliance only"]', 1, 'Loss of recoil or early airway closure prevents full exhalation.', 22),
    (v_topic_id, 'Lung compliance is typically increased in:', '["Pulmonary fibrosis", "Emphysema", "Acute respiratory distress syndrome", "Pneumothorax", "Restrictive chest wall disease"]', 1, 'Destruction of alveolar walls in emphysema reduces the "snap back" force.', 23),
    (v_topic_id, 'Lung compliance is typically decreased in:', '["Emphysema", "Pulmonary fibrosis", "Aging alone", "Mild exercise", "Chronic hyperventilation"]', 1, 'Fibrosis makes the lungs stiff.', 24),
    (v_topic_id, 'In emphysema, increased compliance is mainly due to:', '["Thickened alveolar membranes", "Loss of elastic tissue", "Increased surfactant production", "Reduced dead space", "Bronchial smooth muscle hypertrophy"]', 1, 'Protease-mediated destruction of elastin fibers.', 25),
    (v_topic_id, 'Airway resistance is most sensitive to changes in:', '["Airway radius", "Hemoglobin concentration", "Alveolar surface area", "Pleural fluid volume", "Pulmonary capillary pressure"]', 0, 'Resistance follows Poiseuille Law, which is inversely proportional to radius to the 4th power.', 26),
    (v_topic_id, 'In asthma, airflow limitation is caused primarily by:', '["Increased alveolar compliance only", "Bronchoconstriction and increased airway resistance", "Reduced pulmonary perfusion", "Decreased surfactant", "Thickened pleura only"]', 1, 'Reversible smooth muscle contraction increases resistance.', 27),
    (v_topic_id, 'During expiration in obstructive disease, airflow limitation is worsened by:', '["Increased radial traction", "Dynamic airway compression", "Increased surfactant action", "Decreased intrathoracic pressure", "Reduced residual volume"]', 1, 'Increased pleural pressure during forced exhale collapses floppy airways.', 28),
    (v_topic_id, 'Physiologic dead space is equal to:', '["Tidal volume − residual volume", "Anatomic dead space + alveolar dead space", "Functional residual capacity + tidal volume", "Vital capacity − expiratory reserve volume", "Residual volume + inspiratory reserve volume"]', 1, 'It includes both the conducting zone and non-functional alveoli.', 29),
    (v_topic_id, 'Ventilated alveoli that are not perfused represent:', '["Right-to-left shunt", "Alveolar dead space", "Anatomic shunt", "Restrictive physiology", "Increased compliance only"]', 1, 'V/Q = Infinity. No gas exchange happens.', 30),
    (v_topic_id, 'In pulmonary embolism, the V/Q ratio in affected alveoli tends toward:', '["Zero", "One", "Infinity", "0.8 exactly", "The mixed venous value"]', 2, 'No perfusion (Q=0) results in an infinite V/Q ratio.', 31),
    (v_topic_id, 'Perfused but not ventilated alveoli resemble:', '["Dead space", "Shunt physiology", "Normal V/Q", "Increased diffusion capacity", "Increased lung compliance"]', 1, 'V/Q = 0. This allows deoxygenated blood to return to systemic circulation.', 32),
    (v_topic_id, 'In a true right-to-left shunt, hypoxemia typically:', '["Corrects completely with 100% oxygen", "Does not correct well with 100% oxygen", "Causes respiratory alkalosis only", "Always raises PaCO2 first", "Is due only to low inspired oxygen"]', 1, 'Shunted blood never encounters the increased FiO2.', 33),
    (v_topic_id, 'At the apex of an upright lung, the V/Q ratio is generally:', '["Lower than at the base", "Higher than at the base", "Equal to zero", "Identical throughout the lung", "Lower than venous blood gas ratio"]', 1, 'Gravity-dependent perfusion drops more sharply than ventilation at the apex.', 34),
    (v_topic_id, 'Compared with the base of the lung, apical alveoli usually have:', '["Lower PO2 and higher PCO2", "Higher PO2 and lower PCO2", "Higher PO2 and higher PCO2", "Lower PO2 and lower PCO2", "Equal PO2 and PCO2"]', 1, 'High V/Q means the alveolar gas more closely matches inspired air.', 35),
    (v_topic_id, 'Gas transfer across the alveolar-capillary membrane is described by:', '["Boyle law", "Fick law", "Laplace law", "Henry law only", "Poiseuille law"]', 1, 'The rate of gas transfer is proportional to the concentration gradient and surface area.', 36),
    (v_topic_id, 'Diffusion of a gas across a membrane is increased by:', '["Increased membrane thickness", "Decreased surface area", "Increased partial pressure gradient", "Reduced diffusion coefficient", "Lower solubility only"]', 2, 'Higher gradients drive gases across barriers faster.', 37),
    (v_topic_id, 'In pulmonary fibrosis, diffusion impairment occurs mainly because of:', '["Reduced hemoglobin affinity", "Increased membrane thickness", "Increased alveolar ventilation only", "Reduced pulmonary blood flow only", "Reduced airway resistance"]', 1, 'Scar tissue thickens the barrier.', 38),
    (v_topic_id, 'Oxygen diffusion limitation becomes more apparent during exercise because:', '["Blood transit time through pulmonary capillaries decreases", "Dead space falls to zero", "Hemoglobin affinity increases", "Alveolar PO2 always falls", "Pulmonary perfusion stops in the apex"]', 0, 'Faster cardiac output reduces the contact time between blood and the alveolus.', 39),
    (v_topic_id, 'Carbon dioxide diffuses across the alveolar membrane more readily than oxygen mainly because it:', '["Has lower solubility", "Has higher solubility", "Has no molecular weight", "Has no need for a pressure gradient", "Is transported only dissolved in plasma"]', 1, 'CO2 solubility is ~20x higher than O2.', 40),
    (v_topic_id, 'The strongest stimulus for peripheral chemoreceptors is:', '["PaO2 below about 60 mmHg", "Mild increase in bicarbonate", "Increased lung compliance", "Decreased tidal volume only", "Increased hemoglobin affinity"]', 0, 'Carotid and aortic bodies are primarily sensitive to significant hypoxia.', 41),
    (v_topic_id, 'Central chemoreceptors respond primarily to changes in:', '["Arterial PO2 directly", "CSF H+ generated from CO2 diffusion", "Hemoglobin concentration", "Pleural pressure", "Pulmonary arterial pressure"]', 1, 'Central receptors respond to pH changes in the cerebral spinal fluid.', 42),
    (v_topic_id, 'Carbon dioxide crosses the blood-brain barrier more readily than:', '["Oxygen", "Bicarbonate", "Nitrogen", "Carbon monoxide", "Helium"]', 1, 'Charged ions like bicarbonate cross poorly, whereas lipid-soluble CO2 diffuses easily.', 43),
    (v_topic_id, 'In chronic hypercapnia, central chemoreceptor responsiveness may decline because:', '["CSF bicarbonate rises and buffers H+", "Peripheral chemoreceptors are destroyed", "Alveolar PO2 rises sharply", "Dead space disappears", "Lung compliance always decreases"]', 0, 'Adaptation occurs as the brain buffers the pH changes.', 44),
    (v_topic_id, 'In severe chronic CO2 retention, hypoxemia may become a more important respiratory drive via:', '["Central chemoreceptors", "Peripheral chemoreceptors", "J receptors", "Stretch receptors", "Pleural nociceptors"]', 1, 'The "hypoxic drive" takes over when CO2 sensitivity is lost.', 45),
    (v_topic_id, 'A right shift of the oxygen-hemoglobin dissociation curve is caused by:', '["Decreased temperature", "Decreased 2,3-BPG", "Increased H+ concentration", "Fetal hemoglobin", "Carbon monoxide"]', 2, 'Metabolic waste products like H+ facilitate oxygen release.', 46),
    (v_topic_id, 'A right shift of the oxygen-hemoglobin dissociation curve promotes:', '["Increased oxygen loading in the lungs only", "Increased oxygen unloading in tissues", "Increased hemoglobin affinity for oxygen", "Decreased P50", "Reduced tissue oxygen delivery"]', 1, 'Lower affinity means O2 is released more easily to muscles and organs.', 47),
    (v_topic_id, 'A left shift of the oxygen-hemoglobin dissociation curve is caused by:', '["Increased temperature", "Increased PCO2", "Decreased pH", "Fetal hemoglobin", "Exercise"]', 3, 'HbF has higher affinity to pull oxygen from the mother.', 48),
    (v_topic_id, 'Carbon monoxide poisoning impairs oxygen delivery because CO:', '["Decreases hemoglobin binding to oxygen and shifts curve right", "Binds hemoglobin strongly and shifts curve left", "Increases PaO2 markedly", "Causes severe bronchospasm", "Reduces alveolar ventilation directly"]', 1, 'CO creates an irreversible left shift in the remaining heme groups, preventing unloading.', 49),
    (v_topic_id, 'In high altitude exposure, the initial increase in ventilation is stimulated primarily by:', '["Central chemoreceptors sensing increased CSF H+", "Peripheral chemoreceptors sensing low arterial PO2", "Increased arterial PCO2", "Pulmonary stretch receptors", "Increased bicarbonate concentration"]', 1, 'Hypoxic drive begins via carotid bodies.', 50),
    (v_topic_id, 'A premature infant with respiratory distress syndrome has difficulty maintaining alveolar expansion primarily because of:', '["Increased surfactant production", "Increased surface tension", "Increased pulmonary blood flow", "Decreased airway resistance", "Increased lung compliance"]', 1, 'Lack of surfactant causes high surface tension and alveolar collapse (atelectasis).', 51),
    (v_topic_id, 'Type I pneumocytes are primarily responsible for:', '["Surfactant production", "Gas exchange across the alveolar wall", "Mucus secretion", "Pulmonary vasoconstriction", "Bicarbonate generation"]', 1, 'These are thin cells that make up 95% of the alveolar surface area.', 52),
    (v_topic_id, 'During rapid shallow breathing, alveolar ventilation often falls because:', '["Minute ventilation always decreases", "Dead space makes up a larger fraction of each breath", "Residual volume increases immediately", "Functional residual capacity becomes zero", "Pulmonary capillary blood flow ceases"]', 1, 'Alveolar vent = (TV - DS) * RR. High RR doesn''t help if TV is too low.', 53),
    (v_topic_id, 'If tidal volume becomes equal to anatomic dead space, alveolar ventilation will be:', '["Maximal", "Reduced but adequate", "Zero", "Equal to minute ventilation", "Greater than tidal ventilation"]', 2, 'No air actually reaches the alveoli.', 54),
    (v_topic_id, 'A patient with opioid overdose is expected to have:', '["Decreased PaCO2 and increased pH", "Increased PaCO2 and decreased pH", "Increased PaCO2 and increased pH", "Decreased PaCO2 and decreased pH", "Normal PaCO2 with severe hypoxemia only"]', 1, 'Respiratory depression leads to acidosis.', 55),
    (v_topic_id, 'The primary cause of hypercapnia in hypoventilation is:', '["Increased diffusion limitation", "Decreased alveolar ventilation", "Increased dead space only", "Reduced hemoglobin concentration", "Reduced oxygen consumption"]', 1, 'Simple lack of air movement leads to CO2 retention.', 56),
    (v_topic_id, 'Anxiety-induced hyperventilation most likely produces:', '["Respiratory acidosis", "Metabolic acidosis", "Respiratory alkalosis", "Metabolic alkalosis", "Mixed acidosis"]', 2, 'Loss of CO2 lowers H+ concentration.', 57),
    (v_topic_id, 'Lightheadedness and perioral numbness during acute hyperventilation are most closely related to:', '["Hypercapnia", "Respiratory alkalosis", "Metabolic acidosis", "Increased oxygen content", "Increased diffusion distance"]', 1, 'Alkalosis reduces ionized calcium levels, causing paresthesias.', 58),
    (v_topic_id, 'A patient at high altitude initially hyperventilates mainly because of stimulation of the:', '["Central chemoreceptors by increased CO2", "Peripheral chemoreceptors by low PaO2", "Stretch receptors by increased tidal volume", "J receptors by interstitial edema", "Cortex by high bicarbonate"]', 1, 'Hypoxia is the prime driver at altitude.', 59),
    (v_topic_id, 'After several days at high altitude, renal compensation for respiratory alkalosis involves:', '["Increased bicarbonate retention", "Increased bicarbonate excretion", "Increased hydrogen ion retention", "Decreased urinary pH only", "Decreased chloride excretion"]', 1, 'Kidneys flush bicarb to lower blood pH.', 60),
    (v_topic_id, 'The normal A–a oxygen gradient is most useful for distinguishing hypoventilation from:', '["Metabolic acidosis", "V/Q mismatch and diffusion defects", "Respiratory alkalosis", "Anemia", "Increased oxygen consumption"]', 1, 'Hypoventilation has a normal gradient; V/Q mismatch has an elevated one.', 61),
    (v_topic_id, 'Hypoventilation alone usually causes hypoxemia with a:', '["Increased A–a gradient", "Normal A–a gradient", "Negative A–a gradient", "Markedly widened gradient only during sleep", "Gradient equal to cardiac output"]', 1, 'The gas exchange process is healthy; there''s just not enough fresh air.', 62),
    (v_topic_id, 'V/Q mismatch is a common cause of hypoxemia because:', '["All alveoli have identical ventilation and perfusion", "Some lung units are ventilated or perfused disproportionately", "Alveoli lose all surfactant", "Hemoglobin concentration falls", "Central chemoreceptor drive ceases"]', 1, 'Uneven air/blood distribution is the #1 cause of low PaO2 in clinical practice.', 63),
    (v_topic_id, 'The most common cause of hypoxemia in many lung diseases is:', '["Hypoventilation only", "V/Q mismatch", "Low inspired oxygen only", "Carbon monoxide poisoning", "Anemia"]', 1, 'Most common mechanism in COPD, pneumonia, and heart failure.', 64),
    (v_topic_id, 'In a lung unit with V/Q approaching zero, alveolar gas composition tends toward:', '["Inspired air values", "Arterial blood values", "Mixed venous blood values", "Normal alveolar values", "High PO2 and low PCO2"]', 2, 'A complete shunt matches the incoming venous blood.', 65),
    (v_topic_id, 'In a lung unit with V/Q approaching infinity, alveolar gas composition tends toward:', '["Mixed venous values", "Arterial values", "Inspired air values", "Shunt values", "Capillary equilibrium values"]', 2, 'Dead space ventilation matches the outside inspired air.', 66),
    (v_topic_id, 'The physiologic effect of pulmonary embolism on a ventilated but unperfused alveolus most closely resembles:', '["Shunt", "Increased alveolar dead space", "Restriction", "Decreased compliance", "Diffusion limitation only"]', 1, 'Wasted ventilation.', 67),
    (v_topic_id, 'Oxygen therapy is generally most effective in hypoxemia caused by:', '["Large right-to-left shunt", "V/Q mismatch", "Carbon monoxide poisoning only", "Severe anemia only", "Complete airway obstruction to one lung only"]', 1, 'Simple V/Q mismatch corrected easily with higher FiO2.', 68),
    (v_topic_id, 'Compared with shunt, hypoxemia due to V/Q mismatch usually:', '["Responds better to supplemental oxygen", "Never alters PaCO2", "Produces no symptoms", "Causes identical blood gas findings in all cases", "Always has a normal A–a gradient"]', 0, 'Correction is possible because some air reaches the exchange surface.', 69),
    (v_topic_id, 'Carbon monoxide poisoning often presents with relatively normal PaO2 because:', '["CO raises dissolved oxygen greatly", "PaO2 reflects dissolved oxygen, not hemoglobin-bound oxygen content", "CO does not bind hemoglobin", "The oxygen dissociation curve shifts right", "Ventilation always increases enough to compensate"]', 1, 'PaO2 measures the pressure of gas dissolved in plasma, which isn''t affected by CO.', 70),
    (v_topic_id, 'In carbon monoxide poisoning, oxygen content falls mainly because:', '["Hemoglobin binding sites are occupied by CO", "Dissolved oxygen is absent from plasma", "Diffusion capacity falls sharply", "Airway resistance rises", "Surfactant is destroyed"]', 0, 'CO "kick out" oxygen from hemoglobin.', 71),
    (v_topic_id, 'Carbon monoxide shifts the oxygen-hemoglobin dissociation curve to the:', '["Right, promoting unloading", "Left, impairing unloading", "Right, impairing loading", "Left, improving tissue delivery", "No shift occurs"]', 1, 'The remaining oxygen is trapped tightly on the hemoglobin.', 72),
    (v_topic_id, 'Fetal hemoglobin has higher oxygen affinity than adult hemoglobin because it:', '["Binds 2,3-BPG more strongly", "Binds 2,3-BPG less strongly", "Has higher iron content", "Causes a right shift", "Increases P50"]', 1, 'Weak binding of 2,3-BPG results in higher O2 affinity.', 73),
    (v_topic_id, 'P50 is defined as the:', '["PO2 at which hemoglobin is 50% saturated", "Partial pressure of CO2 in mixed venous blood", "Pressure needed to inflate 50% of alveoli", "Percentage of oxygen dissolved in plasma", "Alveolar PO2 when ventilation equals perfusion"]', 0, 'A standard measure of hemoglobin''s affinity.', 74),
    (v_topic_id, 'A right shift of the oxygen-hemoglobin curve is associated with:', '["Decreased P50", "Increased P50", "Increased affinity for oxygen", "Decreased tissue unloading", "Carbon monoxide poisoning"]', 1, 'Increased P50 means lower affinity.', 75),
    (v_topic_id, 'Increased temperature, increased PCO2, increased H+, and increased 2,3-BPG all tend to:', '["Shift the oxygen-hemoglobin curve left", "Shift the oxygen-hemoglobin curve right", "Prevent oxygen loading in the lungs completely", "Lower P50", "Increase hemoglobin concentration"]', 1, 'Conditions seen in metabolically active tissues.', 76),
    (v_topic_id, 'During exercise, the right shift of the oxygen-hemoglobin dissociation curve is beneficial because it:', '["Reduces oxygen unloading in tissues", "Facilitates oxygen unloading in active tissues", "Increases carbon monoxide binding", "Decreases cardiac output", "Prevents diffusion"]', 1, 'Optimizes oxygen delivery to working muscles.', 77),
    (v_topic_id, 'Most oxygen in blood is transported:', '["Dissolved in plasma", "Bound to hemoglobin", "As bicarbonate", "Bound to albumin", "As carbon monoxide complexes"]', 1, '98% is bound to hemoglobin.', 78),
    (v_topic_id, 'Most carbon dioxide in blood is transported:', '["Bound to hemoglobin as oxyhemoglobin", "Dissolved in plasma only", "As bicarbonate", "As carbonic acid only", "Bound to surfactant"]', 2, '70% is carried as bicarbonate.', 79),
    (v_topic_id, 'Carbon dioxide is converted to bicarbonate in RBCs by:', '["Adenylate cyclase", "Carbonic anhydrase", "Catalase", "Lactate dehydrogenase", "ATP synthase"]', 1, 'Essential enzyme for efficient CO2 transport.', 80),
    (v_topic_id, 'The chloride shift refers to:', '["Chloride moving into RBCs as bicarbonate moves out", "Chloride moving out of RBCs as bicarbonate moves in", "Chloride entering alveoli during exhalation", "Sodium moving into RBCs during hypoxia", "Potassium leaving RBCs in acidosis only"]', 0, 'Maintains electrical neutrality as bicarbonate leaves the RBC.', 81),
    (v_topic_id, 'The Haldane effect refers to the fact that:', '["Oxygenated hemoglobin carries more CO2", "Deoxygenated hemoglobin carries more CO2", "Carbon monoxide increases CO2 carriage", "Bicarbonate cannot enter RBCs", "Oxygen and CO2 never influence each other"]', 1, 'Deoxyhemoglobin is a better proton buffer.', 82),
    (v_topic_id, 'The Bohr effect refers to:', '["Increased CO2 and H+ decreasing hemoglobin’s affinity for oxygen", "Oxygenation of blood reducing CO2 carriage", "Nitrogen dissolving in tissues at depth", "Carbon monoxide shifting the curve left", "Oxygen diffusing better than CO2"]', 0, 'Acidity decreases oxygen binding.', 83),
    (v_topic_id, 'In pulmonary fibrosis, DLCO is typically:', '["Increased", "Decreased", "Unchanged always", "Zero only during exercise", "Higher than emphysema"]', 1, 'Diffusing capacity is low due to thick membrane.', 84),
    (v_topic_id, 'In emphysema, DLCO is often decreased mainly because of:', '["Increased membrane thickness", "Reduced alveolar surface area", "Increased surfactant", "Reduced compliance", "Increased capillary hydrostatic pressure"]', 1, 'Alveolar destruction reduces available area for gas exchange.', 85),
    (v_topic_id, 'A patient with emphysema is expected to have:', '["Increased elastic recoil", "Decreased residual volume", "Increased residual volume", "Decreased compliance", "Increased diffusion due to more surface area"]', 2, 'Air trapping significantly raises RV.', 86),
    (v_topic_id, 'A patient with pulmonary fibrosis is expected to have:', '["Increased total lung capacity", "Decreased total lung capacity", "Increased compliance", "Increased residual volume", "Increased FRC because of air trapping"]', 1, 'Restriction shrinks all lung volumes.', 87),
    (v_topic_id, 'In obstructive disease, expiration is especially difficult because:', '["Airways widen during expiration", "Airways narrow during expiration and may collapse dynamically", "Intrapleural pressure becomes more negative", "Elastic recoil is increased", "Residual volume falls sharply"]', 1, 'Floppy airways are squeezed shut by high pleural pressure.', 88),
    (v_topic_id, 'Beta-2 agonists improve airflow in asthma primarily by:', '["Increasing surfactant secretion", "Relaxing bronchial smooth muscle", "Increasing pulmonary perfusion", "Reducing alveolar surface area", "Increasing mucus viscosity"]', 1, 'Direct bronchodilation.', 89),
    (v_topic_id, 'The major stimulus for central chemoreceptors is:', '["Arterial PO2", "CSF pH changes caused by CO2", "Hemoglobin saturation directly", "Alveolar PO2 only", "Pulmonary artery pressure"]', 1, 'Most important drive for normal respiration.', 90),
    (v_topic_id, 'Peripheral chemoreceptors are located in the:', '["Medulla and pons only", "Carotid and aortic bodies", "Bronchi only", "Pleura and pericardium", "Alveolar epithelium"]', 1, 'Strategically placed to monitor arterial blood content.', 91),
    (v_topic_id, 'Peripheral chemoreceptors respond most strongly to:', '["Mild hyperoxia", "PaO2 less than about 60 mmHg", "Slight rise in bicarbonate only", "Increased lung compliance", "Decreased hemoglobin affinity"]', 1, 'Emergency oxygen sensor.', 92),
    (v_topic_id, 'In a chronic CO2 retainer, giving very high oxygen may worsen hypercapnia partly by:', '["Increasing hypoxic vasoconstriction everywhere", "Reducing hypoxic respiratory drive", "Eliminating alveolar ventilation", "Increasing hemoglobin concentration", "Increasing surfactant secretion"]', 1, 'Loss of the only remaining stimulus for breathing.', 93),
    (v_topic_id, 'During exercise in a healthy person, diffusing capacity of the lung increases because of:', '["Reduced pulmonary capillary blood volume", "Recruitment and distension of pulmonary capillaries", "Increased membrane thickness", "Reduced cardiac output", "Reduced surface area"]', 1, 'Increased blood flow recruits previously inactive capillaries.', 94),
    (v_topic_id, 'Mixed venous PO2 during heavy exercise usually:', '["Increases", "Decreases", "Equals arterial PO2", "Becomes identical to alveolar PO2", "Remains unchanged always"]', 1, 'Heavy muscle extraction leaves venous blood very low in O2.', 95),
    (v_topic_id, 'In left-sided heart failure with pulmonary edema, hypoxemia occurs partly because:', '["Diffusion distance increases", "Surface tension decreases to zero", "Airway resistance disappears", "Hemoglobin affinity rises sharply", "Physiologic dead space falls to zero"]', 0, 'Fluid in the interstitium/alveoli acts as a barrier.', 96),
    (v_topic_id, 'The normal respiratory rhythm is generated primarily in the:', '["Cerebellum", "Medullary respiratory centers", "Carotid body", "Alveolar interstitium", "Pleura"]', 1, 'Located in the brainstem.', 97),
    (v_topic_id, 'J receptors are stimulated mainly by:', '["Lung hyperinflation only", "Increased interstitial fluid in the lungs", "Low hemoglobin concentration", "Bronchial smooth muscle contraction only", "Low arterial oxygen content directly"]', 1, 'Juxtacapillary receptors respond to engorgement/edema.', 98),
    (v_topic_id, 'During quiet expiration, air leaves the lungs mainly because:', '["The diaphragm contracts", "Elastic recoil raises alveolar pressure above atmospheric pressure", "Alveolar pressure becomes negative", "Intrapleural pressure becomes more negative", "Active abdominal contraction is required normally"]', 1, 'Passive process in healthy individuals.', 99),
    (v_topic_id, 'Which statement best distinguishes minute ventilation from alveolar ventilation?', '["Minute ventilation excludes dead space, alveolar ventilation includes it", "Alveolar ventilation excludes dead space, minute ventilation includes it", "They are always identical", "Minute ventilation is measured only during exercise", "Alveolar ventilation equals residual volume × respiratory rate"]', 1, 'Efficiency of fresh air intake relies on clearing dead space.', 100);
